package de.lazytv.pro.cms;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.*;import android.util.Base64;import android.view.*;import android.widget.*;import java.io.*;
public class IslamicHubActivity extends Activity{
 protected void onCreate(Bundle b){super.onCreate(b);LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(18,14,18,14);root.setBackgroundColor(Color.rgb(6,17,31));TextView h=new TextView(this);h.setText("ISLAM");h.setTextColor(Color.WHITE);h.setTextSize(28);h.setTypeface(null,1);root.addView(h);TextView s=new TextView(this);s.setText("Zgjidh rubrikën");s.setTextColor(Color.rgb(175,196,216));s.setTextSize(15);root.addView(s);LinearLayout row=new LinearLayout(this);row.setOrientation(LinearLayout.HORIZONTAL);row.setPadding(0,18,0,0);root.addView(row,new LinearLayout.LayoutParams(-1,0,1));String[] names={"Filma Islam","Filma Serik Islam","Ligjërata Islame","Dokumentare Islame","Filma Vizatimor Islam"};String[] cats={IslamicCmsConfig.FILMS,IslamicCmsConfig.SERIES,IslamicCmsConfig.LECTURES,IslamicCmsConfig.DOCUMENTARIES,IslamicCmsConfig.KIDS};Bitmap sheet=sheet();for(int i=0;i<5;i++){final String cat=cats[i];LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(5,5,5,5);ImageButton im=new ImageButton(this);im.setBackgroundColor(Color.rgb(11,29,51));im.setScaleType(ImageView.ScaleType.FIT_CENTER);if(sheet!=null){int cw=sheet.getWidth()/4,ch=sheet.getHeight()/2,idx=i+3;if(idx<8)im.setImageBitmap(Bitmap.createBitmap(sheet,(idx%4)*cw,(idx/4)*ch,cw,ch));}im.setOnClickListener(v->open(cat));box.addView(im,new LinearLayout.LayoutParams(-1,0,1));TextView t=new TextView(this);t.setText(names[i]);t.setTextColor(Color.WHITE);t.setTextSize(15);t.setGravity(Gravity.CENTER);t.setPadding(2,8,2,8);box.addView(t,new LinearLayout.LayoutParams(-1,52));row.addView(box,new LinearLayout.LayoutParams(0,-1,1));}}
 private void open(String c){Intent i=new Intent(this,IslamicCatalogActivity.class);i.putExtra(IslamicCatalogActivity.EXTRA_CATEGORY,c);startActivity(i);}
 private Bitmap sheet(){try{InputStream in=getAssets().open("home_tiles.jpg.b64");ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[4096];int n;while((n=in.read(b))>0)out.write(b,0,n);in.close();byte[] raw=Base64.decode(out.toString("UTF-8").trim(),Base64.DEFAULT);return BitmapFactory.decodeByteArray(raw,0,raw.length);}catch(Exception e){return null;}}
}